/* Simple DataTables Implementation for the project */
(function($) {
    $.fn.DataTable = function(options) {
        var defaults = {
            processing: true,
            serverSide: false,
            data: [],
            columns: [],
            pageLength: 10,
            lengthMenu: [[10, 25, 50, 100], [10, 25, 50, 100]],
            language: {
                search: "_INPUT_",
                searchPlaceholder: "Search...",
                lengthMenu: "Show _MENU_ entries",
                info: "Showing _START_ to _END_ of _TOTAL_ entries",
                paginate: {
                    previous: '&lt;',
                    next: '&gt;'
                }
            },
            dom: '<"dataTables_wrapper"<"dataTables_top"lf>rt<"dataTables_bottom"ip>>',
            drawCallback: null
        };
        
        var settings = $.extend({}, defaults, options);
        var $table = $(this);
        var currentPage = 1;
        var filteredData = [];
        
        function render() {
            var $wrapper = $('<div class="dataTables_wrapper"></div>');
            $table.wrap($wrapper);
            
            // Add controls
            var $controls = $(`
                <div class="flex flex-col sm:flex-row justify-between mb-4">
                    <div class="dataTables_length mb-2 sm:mb-0">
                        <label>Show 
                            <select class="px-2 py-1 border rounded dark:bg-gray-700 dark:border-gray-600">
                                ${settings.lengthMenu[0].map(v => `<option value="${v}">${v}</option>`).join('')}
                            </select> entries
                        </label>
                    </div>
                    <div class="dataTables_filter">
                        <label>Search: 
                            <input type="search" class="px-3 py-1 border rounded dark:bg-gray-700 dark:border-gray-600" placeholder="${settings.language.searchPlaceholder}">
                        </label>
                    </div>
                </div>
            `);
            
            $table.before($controls);
            
            // Add footer
            var $footer = $(`
                <div class="flex flex-col sm:flex-row justify-between mt-4">
                    <div class="dataTables_info text-gray-600 dark:text-gray-400"></div>
                    <div class="dataTables_paginate"></div>
                </div>
            `);
            
            $table.after($footer);
            
            // Bind events
            $controls.find('select').on('change', function() {
                settings.pageLength = parseInt($(this).val());
                currentPage = 1;
                updateTable();
            });
            
            $controls.find('input').on('keyup', function() {
                var searchTerm = $(this).val().toLowerCase();
                if (searchTerm) {
                    filteredData = settings.data.filter(row => {
                        return Object.values(row).some(val => 
                            val !== null && val !== undefined && String(val).toLowerCase().includes(searchTerm)
                        );
                    });
                } else {
                    filteredData = settings.data;
                }
                currentPage = 1;
                updateTable();
            });
            
            // Initial render
            filteredData = settings.data;
            updateTable();
        }
        
        function updateTable() {
            var start = (currentPage - 1) * settings.pageLength;
            var end = start + settings.pageLength;
            var pageData = filteredData.slice(start, end);
            
            // Clear tbody
            var $tbody = $table.find('tbody');
            $tbody.empty();
            
            // Add rows
            if (pageData.length === 0) {
                $tbody.append(`<tr><td colspan="${settings.columns.length}" class="text-center py-4">No data available</td></tr>`);
            } else {
                pageData.forEach(row => {
                    var $tr = $('<tr></tr>');
                    settings.columns.forEach(col => {
                        var value = '';
                        if (col.render) {
                            value = col.render(row[col.data], row);
                        } else {
                            value = row[col.data] || '';
                        }
                        $tr.append(`<td class="px-6 py-4">${value}</td>`);
                    });
                    $tbody.append($tr);
                });
            }
            
            // Update info
            var $info = $table.parent().find('.dataTables_info');
            if (filteredData.length === 0) {
                $info.text('No entries to show');
            } else {
                var infoStart = start + 1;
                var infoEnd = Math.min(end, filteredData.length);
                $info.text(`Showing ${infoStart} to ${infoEnd} of ${filteredData.length} entries`);
            }
            
            // Update pagination
            updatePagination();
            
            // Call drawCallback
            if (settings.drawCallback) {
                settings.drawCallback();
            }
        }
        
        function updatePagination() {
            var $paginate = $table.parent().find('.dataTables_paginate');
            $paginate.empty();
            
            var totalPages = Math.ceil(filteredData.length / settings.pageLength);
            
            if (totalPages <= 1) return;
            
            var $pagination = $('<div class="flex space-x-1"></div>');
            
            // Previous button
            if (currentPage > 1) {
                $pagination.append(`<button class="paginate_button px-3 py-1 border rounded hover:bg-gray-100 dark:hover:bg-gray-700" data-page="${currentPage - 1}">Previous</button>`);
            }
            
            // Page numbers
            for (var i = 1; i <= totalPages; i++) {
                if (i === currentPage) {
                    $pagination.append(`<button class="paginate_button current px-3 py-1 border rounded bg-blue-500 text-white" data-page="${i}">${i}</button>`);
                } else {
                    $pagination.append(`<button class="paginate_button px-3 py-1 border rounded hover:bg-gray-100 dark:hover:bg-gray-700" data-page="${i}">${i}</button>`);
                }
            }
            
            // Next button
            if (currentPage < totalPages) {
                $pagination.append(`<button class="paginate_button px-3 py-1 border rounded hover:bg-gray-100 dark:hover:bg-gray-700" data-page="${currentPage + 1}">Next</button>`);
            }
            
            $paginate.append($pagination);
            
            // Bind pagination events
            $pagination.find('.paginate_button').on('click', function() {
                currentPage = parseInt($(this).data('page'));
                updateTable();
            });
        }
        
        // Public methods
        var api = {
            ajax: {
                reload: function() {
                    if (settings.ajax && settings.ajax.url) {
                        $.ajax({
                            url: settings.ajax.url,
                            method: settings.ajax.method || 'GET',
                            success: function(response) {
                                settings.data = response.data || response;
                                filteredData = settings.data;
                                updateTable();
                            }
                        });
                    }
                }
            },
            clear: function() {
                settings.data = [];
                filteredData = [];
                updateTable();
            },
            rows: {
                add: function(data) {
                    settings.data.push(data);
                    filteredData = settings.data;
                    updateTable();
                }
            },
            draw: function() {
                updateTable();
            }
        };
        
        // Initialize
        if (settings.ajax && settings.ajax.url) {
            $.ajax({
                url: settings.ajax.url,
                method: settings.ajax.method || 'GET',
                success: function(response) {
                    settings.data = response.data || response;
                    render();
                }
            });
        } else {
            render();
        }
        
        // Store API
        $table.data('datatable', api);
        
        return api;
    };
})(jQuery);